/* Byte ranges for the cached opening MP4s, including Safari's initial bytes=0-1 request. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.RayVideoRange=api;})(typeof globalThis!=='undefined'?globalThis:this,()=>{
 function parse(header,length){const m=/^bytes=(\d*)-(\d*)$/.exec(String(header||'').trim());if(!m||!Number.isSafeInteger(length)||length<1||(!m[1]&&!m[2]))return null;let start,end;if(!m[1]){const suffix=Number(m[2]);if(!Number.isSafeInteger(suffix)||suffix<1)return null;start=Math.max(0,length-suffix);end=length-1;}else{start=Number(m[1]);end=m[2]?Math.min(length-1,Number(m[2])):length-1;}return Number.isSafeInteger(start)&&Number.isSafeInteger(end)&&start>=0&&start<length&&end>=start?{start,end}:null;}
 async function response(cached,header){const data=await cached.arrayBuffer(),range=parse(header,data.byteLength);if(!range)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+data.byteLength,'Accept-Ranges':'bytes'}});const h=new Headers(cached.headers);h.set('Content-Type','video/mp4');h.set('Accept-Ranges','bytes');h.set('Content-Range','bytes '+range.start+'-'+range.end+'/'+data.byteLength);h.set('Content-Length',String(range.end-range.start+1));h.delete('Content-Encoding');return new Response(data.slice(range.start,range.end+1),{status:206,headers:h});}
 return{parse,response};
});
